const payload = $input.first().json;
const data = payload.data || payload;

const roleTitles = {
  'user': 'Customer 👤',
  'shop_owner': 'Medical Shop Owner 🏥',
  'rider': 'Delivery Rider 🏍️'
};

const title = roleTitles[data.role] || data.roleDisplay || 'User';

return [{
  json: {
    subject: `🎉 Welcome to MediFind, ${data.name || 'Friend'}! (${title})`,
    body: `New user registration on MediFind.\n\n` +
          `Name: ${data.name || 'N/A'}\n` +
          `Email: ${data.email}\n` +
          `Account Type: ${title}\n` +
          `User ID: ${data.userId}\n\n` +
          `Registered at: ${payload.timestamp || new Date().toISOString()}`,
    userId: data.userId,
    email: data.email,
    name: data.name,
    role: data.role,
    isRider: data.role === 'rider',
    isShopOwner: data.role === 'shop_owner',
    isCustomer: data.role === 'user'
  }
}];
